const todos = [
  { id: 1, text: 'Buy milk', done: true },
  { id: 2, text: 'Walk the dog', done: false },
  { id: 3, text: 'Write the report', done: false },
]

function TodoList() {
  return (
    <ul>
      {todos.map(todo => (
        <li key="todo" style={{ textDecoration: todo.done ? 'line-through' : 'none' }}>
          {todo.text}
        </li>
      ))}
    </ul>
  )
}

export default TodoList
